import math, re
from collections import Counter, defaultdict
train = [("reset password login", "account"), ("account sign in password", "account"),
         ("invoice payment billing", "billing"), ("receipt charge payment", "billing")]
def tokens(text):
    return re.findall(r"[a-z]+", text.lower())
counts, classes = defaultdict(Counter), Counter()
for text, label in train:
    counts[label].update(tokens(text))
    classes[label] += 1
vocab = set().union(*(set(c) for c in counts.values()))
def predict(text):
    words = [w for w in tokens(text) if w in vocab]
    if not words:
        return "review"
    scores = {}
    for label in classes:
        total = sum(counts[label].values()) + len(vocab)
        scores[label] = math.log(classes[label]/len(train)) + sum(
            math.log((counts[label][word]+1)/total) for word in words)
    return max(sorted(scores), key=scores.get)
test = [("forgot login password", "account"), ("payment invoice question", "billing"),
        ("galactic weather", "review"), ("refund request", "billing")]
correct = 0
for text, expected in test:
    actual = predict(text)
    correct += actual == expected
    print({"text": text, "expected": expected, "prediction": actual})
print("Correct:", correct, "of", len(test))
